// /frontend-react/src/App.js

import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import MedicalDashboard from './components/MedicalDashboard';
import AppointmentFlow from './components/AppointmentFlow';
import TransportStatus from './components/TransportStatus';
import HeaderBar from './components/HeaderBar';

// Mock data for the flow demonstration
const mockAppointmentData = {
    date: 'Dec 10',
    time: '10:00 AM',
    hasTransportBooked: false,
};

function App() {
    const [currentPage, setCurrentPage] = useState('dashboard'); 
    const [isEasyMode] = useState(true); 

    const handleNotificationClick = () => {
        // Notification click goes straight to the detailed Appointment flow
        setCurrentPage('appointment');
    };

    const renderPage = () => {
        // --- Level 1: Main Dashboard (4 Icons) ---
        if (currentPage === 'dashboard') {
            return (
                <Dashboard
                    isEasyMode={isEasyMode}
                    goToMedical={() => setCurrentPage('medical-dashboard')}
                />
            );
        }

        // --- Level 2: Medical Sub-Dashboard (3 Icons) ---
        if (currentPage === 'medical-dashboard') {
             return (
                <MedicalDashboard
                    isEasyMode={isEasyMode}
                    goToPage={setCurrentPage} 
                />
            );
        }

        // --- Level 3: Appointment Flow (Booking Steps) ---
        if (currentPage === 'appointment') {
            return (
                <AppointmentFlow
                    isEasyMode={isEasyMode}
                    appointment={mockAppointmentData}
                    goToTransportStatus={() => setCurrentPage('transport')} 
                    goToMedicalDashboard={() => setCurrentPage('medical-dashboard')} 
                />
            );
        }

        // --- Level 3: Transportation Status (Driver Info) ---
        if (currentPage === 'transport') {
            return (
                <TransportStatus
                    isEasyMode={isEasyMode}
                    goToAppointmentFlow={() => setCurrentPage('appointment')} 
                    goToMedicalDashboard={() => setCurrentPage('medical-dashboard')} 
                />
            );
        }

        // --- Level 3: Medicine Reminder (Placeholder) ---
        if (currentPage === 'medicine') {
            return (
                <div style={{ padding: '0 20px 20px 20px', textAlign: 'center' }}>
                    <HeaderBar title="Medicine Reminders" onBackClick={() => setCurrentPage('medical-dashboard')} isEasyMode={isEasyMode} />
                    <h2 style={{fontSize: isEasyMode ? '48px' : '30px', marginTop: '20px'}}>💊 Medicine Reminders</h2>
                    <p style={{fontSize: isEasyMode ? '30px' : '16px'}}>Feature not built yet. Tap the arrow above to go back.</p>
                </div>
            );
        }
    };

    return (
        // Outer container: Centers the content on a wide screen
        <div style={{
            padding: '20px',
            backgroundColor: '#f0f0f0', 
            minHeight: '100vh', 
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'flex-start',
        }}>
            {/* Inner container: Main app card, handles layout balance */}
            <div 
                style={{
                    maxWidth: '900px', 
                    width: '100%',
                    margin: '20px 0',
                    border: '1px solid #ccc',
                    borderRadius: '10px',
                    boxShadow: '0 10px 30px rgba(0,0,0,0.1)',
                    backgroundColor: '#ffffff',
                    overflow: 'hidden', 
                }}
                className={`App ${isEasyMode ? 'easy-mode-theme' : 'standard-theme'}`}
            >
                {/* Mock 3-Day Notification Banner */}
                {currentPage === 'dashboard' && (
                    <div 
                        onClick={handleNotificationClick}
                        style={{ 
                            padding: '15px', 
                            backgroundColor: '#ffdddd', 
                            color: 'red',
                            textAlign: 'center',
                            cursor: 'pointer',
                            fontSize: isEasyMode ? '28px' : '16px',
                            fontWeight: 'bold',
                            borderBottom: '2px solid red',
                            position: 'sticky', 
                            top: 0,
                            zIndex: 10
                        }}
                    >
                        🚨 **NOTIFICATION: Appointment Soon! Tap Here!** 🚨
                    </div>
                )}
                
                {renderPage()}
            </div>
        </div>
    );
}

export default App;
